/* ===== 身子区 =====
   在这块空地上写两招的身子：
   · fish_pack：每碗 {per} 条、一共 {bowls} 碗，还总条数；
   · fish_left：整袋减掉吃掉的，还剩下的数。 */

referenceSolutionTemplate:
#include <stdio.h>

/* ===== 招牌区 ===== */
int fish_pack(int per, int bowls);
int fish_left(int total, int eaten);

int main(void) {
    int bag = fish_pack({per}, {bowls});
    printf("码好 %d 条\n", bag);
    printf("还剩 %d 条\n", fish_left(bag, {eaten}));
    return 0;
}

/* ===== 身子区 ===== */
int fish_pack(int per, int bowls) {
    return per * bowls;
}

int fish_left(int total, int eaten) {
    return total - eaten;
}
